document.addEventListener('DOMContentLoaded', () => {
    // Upload Submit
    document.querySelectorAll('.upload-profile-container input[type="file"]').forEach((uploadInput) => {
        uploadInput.addEventListener('change', (e) => {
            e.preventDefault();

            const value = uploadInput.value;
            const file = uploadInput.files[0];

            if (!value || !file) {
                return false;
            }

            const url = document.querySelector('form').getAttribute('action');
            const args = {};

            document.querySelectorAll('input[type="hidden"][value="1"]').forEach((input) => {
                args[input.name] = 1;
            });

            const formData = new FormData();

            Object.entries(args).forEach(([key, value]) => {
                formData.append(key, value);
            });

            // convert slashes
            const convertedValue = value.replace(/[\\\\]+/g, '/');

            // extract name
            const name = convertedValue.substr(convertedValue.lastIndexOf('/') + 1);

            // append file
            formData.append('profile_file', file, name);

            fetch(`${url}&task=profiles.import`, {
                method: 'POST',
                headers: {
                    'X-Requested-With': 'XMLHttpRequest'
                },
                body: formData
            }).then((response) => {
                if (!response.ok) {
                    throw new Error('Network error');
                }
                
                return response.json();
            }).then((data) => {
                document.location.href = data.data.redirect || 'index.php?option=com_jce&view=profiles';
                // eslint-disable-next-line dot-notation
            }).catch((error) => {
                console.error('Error:', error);
            });
        });
    });
});
